    if not row_runs or not col_runs:
        return g

    # Ignore cropped edge tiles by retaining runs of the regular tile size.
    rh = Counter(b - a + 1 for a, b in row_runs).most_common(1)[0][0]
    cw = Counter(b - a + 1 for a, b in col_runs).most_common(1)[0][0]
    row_runs = [(a, b) for a, b in row_runs if b - a + 1 == rh]
    col_runs = [(a, b) for a, b in col_runs if b - a + 1 == cw]
