            if color != background:
                by_color.setdefault(color, []).append(ci)
        for color, indices in by_color.items():
            for left, right in zip(indices, indices[1:]):
                for boundary in {left, right - 1}:
                    a, b = col_runs[boundary]
                    for c in range(b + 1, col_runs[boundary + 1][0]):
                        g[r][c] = color

    for ci, c in enumerate(ccenters):
        by_color = {}
        for ri, colorrow in enumerate(colors):
            color = colorrow[ci]
            if color != background:
                by_color.setdefault(color, []).append(ri)
        for color, indices in by_color.items():
            for top, bottom in zip(indices, indices[1:]):
                for boundary in {top, bottom - 1}:
                    a, b = row_runs[boundary]
                    for r in range(b + 1, row_runs[boundary + 1][0]):
                        g[r][c] = color
    return g


